`timescale 1ns/1ps
module tb;
reg clk=0;always #5 clk=~clk;
reg rst_n=0,valid=0;reg[7:0]byte_data=0;
wire[7:0]replay_data,mask;wire[5:0]idx;wire replay_valid,start,ok,err;
wire[31:0]rid,inj;wire[15:0]codes;wire[1:0]source;
gwx_report_debug dut(clk,rst_n,valid,byte_data,replay_data,idx,replay_valid,start,rid,inj,mask,codes,source,ok,err);
reg[7:0]expected[0:63];integer checks=0,n;
task send(input string s);integer i;begin
 for(i=0;i<s.len();i=i+1)begin @(negedge clk);valid=1;byte_data=s[i];@(negedge clk);valid=0;end
end endtask
task replay_check(input[31:0]r,input[31:0]id,input[7:0]m,input[15:0]c);integer j,k,timeout;begin
 if(!ok||err||rid!==r||inj!==id||mask!==m||codes!==c||source!==1)$fatal(1,"metadata r=%h i=%h mask=%h codes=%h ok=%b err=%b bad=%b seench=%h pos=%d",rid,inj,mask,codes,ok,err,dut.bad,dut.channels_seen,dut.pos);
 // Check two consecutive full replays, including capture after report completion.
 for(k=0;k<2;k=k+1)begin
  timeout=0;while(!start)begin @(negedge clk);timeout=timeout+1;if(timeout>1100)$fatal(1,"no periodic replay");end
  for(j=0;j<512;j=j+1)begin
   if(!replay_valid||idx!==(j/8)||replay_data!==expected[j/8])$fatal(1,"sample mismatch at %d index=%d byte=%h expected=%h",j,idx,replay_data,expected[j/8]);
   if(start!==(j==0))$fatal(1,"bad start width");@(negedge clk);
  end
  if(replay_valid)$fatal(1,"replay valid too long");
 end
 checks=checks+1;
end endtask
